CREATE FUNCTION public.voorraad_kassa_dekking(p_vestiging text,p_van date,p_tot date,p_ids jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
SELECT public.is_service_call() AND p_van<=p_tot AND jsonb_array_length(p_ids)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_ids)x WHERE NOT EXISTS(SELECT 1 FROM public.kassa_verkoop_dag d WHERE d.vestiging=p_vestiging AND d.lightspeed_product_id=x->>'id')) AND NOT EXISTS(SELECT 1 FROM generate_series(p_van::timestamp,p_tot::timestamp,interval '1 day')g WHERE public.mep_is_open(p_vestiging,g::date) AND NOT EXISTS(SELECT 1 FROM public.kassa_verkoop_dag d WHERE d.vestiging=p_vestiging AND d.datum=g::date)) $$;
REVOKE ALL ON FUNCTION public.voorraad_kassa_dekking(text,date,date,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.voorraad_kassa_dekking(text,date,date,jsonb) TO service_role,postgres;
COMMENT ON FUNCTION public.voorraad_kassa_dekking(text,date,date,jsonb) IS 'Service-only dekking: bekende product-ids en kassagegevens voor elke open dag; gesloten dagen geen nepverkoop. Ontbrekende bron blijft onbekend, bevestigde nul apart.';
CREATE OR REPLACE VIEW public.v_voorraad_bewegingen WITH(security_invoker=true) AS SELECT b.* FROM(SELECT DISTINCT vestiging FROM public.voorraad_artikel WHERE public.heeft_vestiging(auth.uid(),vestiging) OR public.is_service_call())a CROSS JOIN LATERAL public.voorraad_bewegingen_lezen(a.vestiging)b;
DO $do$ DECLARE d text;BEGIN
SELECT pg_get_functiondef('public.leercurve_bijwerken()'::regprocedure) INTO d;
d:=replace(d,'SELECT CASE WHEN count(*)>0 THEN sum(d.aantal*(m->>''per_eenheid'')::numeric) END INTO k','SELECT CASE WHEN public.voorraad_kassa_dekking(l.vestiging,(l.gegevens->>''periode_van'')::date,(l.gegevens->>''periode_tot'')::date,l.gegevens->''kassa_ids'') THEN coalesce(sum(d.aantal*(m->>''per_eenheid'')::numeric),0) END INTO k');
d:=replace(d,'ok:=ok AND t.moment=t.eind_moment','ok:=ok AND public.voorraad_kassa_dekking(a.vestiging,public.voorraad_daggrens(t.datum,t.moment),public.voorraad_daggrens(t.eind_datum,t.eind_moment)-1,(SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',lightspeed_product_id,''per_eenheid'',factor)),''[]''::jsonb) FROM public.voorraad_verbruik_koppeling WHERE voorraad_artikel_id=a.id)) AND t.moment=t.eind_moment');
EXECUTE d;
SELECT pg_get_functiondef('public.bestelbot_advies_loggen(text,date,date,jsonb,text)'::regprocedure) INTO d;
d:=replace(d,'werkelijk_besteld=NULL,later_verkocht=NULL,later_geteld=NULL,afwijking=NULL,leerstatus=''onvolledig''','werkelijk_besteld=CASE WHEN advies_log.gegevens=excluded.gegevens AND advies_log.eenheid IS NOT DISTINCT FROM excluded.eenheid THEN advies_log.werkelijk_besteld END,later_verkocht=CASE WHEN advies_log.gegevens=excluded.gegevens AND advies_log.eenheid IS NOT DISTINCT FROM excluded.eenheid THEN advies_log.later_verkocht END,later_geteld=CASE WHEN advies_log.gegevens=excluded.gegevens AND advies_log.eenheid IS NOT DISTINCT FROM excluded.eenheid THEN advies_log.later_geteld END,afwijking=CASE WHEN advies_log.gegevens=excluded.gegevens AND advies_log.eenheid IS NOT DISTINCT FROM excluded.eenheid THEN excluded.advies-advies_log.later_verkocht END,leerstatus=CASE WHEN advies_log.gegevens=excluded.gegevens AND advies_log.eenheid IS NOT DISTINCT FROM excluded.eenheid THEN advies_log.leerstatus ELSE ''onvolledig'' END');
EXECUTE d;
END $do$;